fn handle_line_defense(version, p2, player, ctx, line, p6) -> bool

scope = *(ctx+0x08)                       // 64B

// 544
if !rule_scope::line_exists(scope, line) { return false }

// 549 (a) rule_scope::morgard_exists 인라인 → TutorialType::spawn_epic(runner.rs:263)
t = *(scope+0x38) as i8                    // range 0..9
if (t - 1) ult 6 { return false }          // t ∈ 1..=6 이면 즉시 false

// 549 (b)
game  = *(ctx+0x00)                        // AbstractGameWithCache(8840B)
data  = *(game+0x00); vt = *(game+0x08)    // &dyn 팻포인터(data, vtable)
opt   = (*(vt+0x40))(data)                 // {tag:i64, ptr} = GameMode::as_moba()
if opt.tag != 0 { core::option::unwrap_failed(..) }    // .unwrap() — 이 함수의 유일한 패닉 경로
moba  = opt.ptr
team  = *(player+0x930) as usize
opp   = 1 - team                           // opp >= 2 면 panic_bounds_check(len 2)
if *(moba+0x240 + 8*opp) == 0 { return false }         // MobaMode::remain_epic_time(opp) == 0

// 553  AbstractGameWithCache::tower(line, team) 인라인 (simulation.rs:1822)
if team >= 2 { panic_bounds_check(len 2) }
(a,b) = match line { 0 => (0x180,0x190), 1 => (0x1a0,0x1b0), 2 => (0x1c0,0x1d0) }
tower = Option(*(game+a+8*team)).or(Option(*(game+b+8*team)))   // Option<&Entity>

// 554~559
v     = *(game + 0x130 + 32*team)          // bumpalo Vec<&Entity>: data@+0, len@+24
near  = v.iter().min_by_key(|e| {          // 키 클로저 = handle_line_defense::closure#0 @555
            let (sx,sy) = LineType::get_start_position(line, *(scope+0x08), team);  // 556
            abs_diff(*(e+0x660), sx)^2 + abs_diff(*(e+0x668), sy)^2                 // 557
        }).map(|e| *e);                     // 559 (&&Entity → &Entity 역참조)
// 주: 첫 원소의 키는 이 함수 본문에서 직접 계산해 fold 헬퍼의 초기값으로 넘긴다.
//     len == 0 이면 near = None.

target = tower.or(near)                    // tower 가 Some 이면 tower 우선
if target.is_none() { return false }       // 565 — IR 상 패닉 없이 false 반환

// 567
if !has_line_defense_threat(player, ctx, line, *(target+0x5c0)) { return false }

// 571
enemies = AbstractGameWithCache::champions(game, opp, *(scope+0x00))   // Vec<&Entity>

// 572  (필터 술어 = closure#2)
bb = *(ctx+0x10) + 744*opp                 // 상대 팀 Blackboard(744B)
n  = 0
for e in enemies {
    if Blackboard::is_recent_visible(bb, data, vt, player, e)
       && Entity::distance_sq(e, target) < 40000000001 { n += 1 }
}
// enemies 는 여기서 drop (bumpalo Vec/RawVec Drop, 언와인드 경로에 cleanuppad 존재)

// 575
st   = PlayerState::strategy(player, p2, data, vt)   // 24B sret
flag = *(st+0x0E) != 0                     // 576

// 578
return if flag { n == 1 || n == 2 }        // (n-1) ult 2
       else     { n >= 2 }                 // n ugt 1
